create role anon nologin;
create role authenticated nologin;
create schema auth;
create table auth.users(id uuid primary key,email text,encrypted_password text,created_at timestamptz,updated_at timestamptz);
create table auth.sessions(id uuid primary key,user_id uuid references auth.users,created_at timestamptz,updated_at timestamptz,aal text);
create table auth.mfa_factors(id uuid primary key,user_id uuid references auth.users,friendly_name text,factor_type text,status text,created_at timestamptz,updated_at timestamptz,secret text);
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
create function auth.uid() returns uuid language sql stable as $$select nullif(auth.jwt()->>'sub','')::uuid$$;
grant usage on schema auth to authenticated,anon;
grant execute on all functions in schema auth to authenticated,anon;
create table public.profiles(id uuid primary key references auth.users,role text,admin_role text,staff_status text default 'active',job_title text,mfa_required boolean default false,must_change_password boolean default false,password_changed_at timestamptz,updated_at timestamptz default now());
create table public.admin_modules(module_key text primary key);
insert into public.admin_modules values('finance'),('security');
create table public.admin_role_permissions(role_key text,module_key text,can_view boolean,can_create boolean,can_edit boolean,can_delete boolean,can_approve boolean,can_export boolean);
insert into public.admin_role_permissions values('finance','finance',true,true,true,false,false,true);
create table public.admin_user_permissions(user_id uuid,module_key text,action_key text,allowed boolean,expires_at timestamptz);
create table public.pricing_settings(id text,min_margin_percent numeric,warning_margin_percent numeric,dealer_discount_percent numeric,epc_discount_percent numeric,distributor_discount_percent numeric,project_discount_percent numeric,enforce_min_margin boolean,allow_admin_override boolean,updated_by uuid,updated_at timestamptz);
alter table public.profiles enable row level security;
alter table public.admin_modules enable row level security;
create policy profiles_own on public.profiles to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy module_read on public.admin_modules for select to authenticated using(true);
grant select,update on public.profiles to authenticated;
grant select on public.admin_modules to authenticated;
